use vstd::prelude::*;

verus! {

    /// Returns the concatenation of slices `a` and `b`.
    /// Ensures
    ///   1. result.len() == a.len() + b.len()
    ///   2. for all i < a.len(): result[i] == a[i]
    ///   3. for all j < b.len(): result[a.len() + j] == b[j]
    pub fn concat(a: &Slice<i32>, b: &Slice<i32>) -> Vec<i32>
        ensures |res: &Vec<i32>|
            res@.len() == a@.len() + b@.len() &&
            (forall |i: nat| i < a@.len()  ==> res@[i] == a@[i]) &&
            (forall |j: nat| j < b@.len()  ==> res@[a@.len() + j] == b@[j])
    {
        let total = a@.len() + b@.len();
        let mut res = Vec::with_capacity(total);

        // First loop: push all of `a`.
        let mut i: usize = 0;
        while i < a@.len() {
            invariant i <= a@.len();
            invariant res.len() == i;
            invariant forall |k: nat| k < i ==> res@[k] == a@[k];
            decreases a@.len() - i;

            // push the next element of `a`
            res.push(a.index(i));
            i += 1;
        }

        // Second loop: push all of `b`.
        let mut j: usize = 0;
        while j < b@.len() {
            invariant j <= b@.len();
            invariant res.len() == a@.len() + j;
            invariant
                // first all of `a` still in place
                (forall |k: nat| k < a@.len() ==> res@[k] == a@[k]) &&
                // plus the j elements of `b` we've pushed so far
                (forall |l: nat| l < j ==> res@[a@.len() + l] == b@[l]);
            decreases b@.len() - j;

            // push the next element of `b`
            res.push(b.index(j));
            j += 1;
        }

        res
    }

} // verus!